-- Moves the clubs the position rule gets wrong: gyms far from their club's
-- address, and Monaco.
-- Generated by scripts/ffbb-import/build_migration.py --positions.
-- A club no longer at its seeded position is left alone.
UPDATE clubs AS c
SET latitude = v.latitude::decimal(10,8), longitude = v.longitude::decimal(11,8)
FROM (VALUES
('ARA0063034', '45.6769', '3.16606', '45.79557', '3.073493'),
('ARA0069152', '45.73548', '4.911201', '45.694615', '5.125126'),
('ARA0073098', '45.542518', '6.303898', '45.666412', '5.91263'),
('GES0054022', '48.694044', '6.575156', '48.806351', '6.724828'),
('GES0067051', '48.960305', '2.256746', '48.557861', '7.7593'),
('GES0067103', '48.263968', '7.451766', '48.263334', '7.233176'),
('GES0067147', '48.54582', '7.705552', '49.05726', '7.418603'),
('HDF0059104', '50.692113', '2.879124', '50.738837', '3.085418'),
('HDF0080020', '49.950719', '2.630861', '49.935467', '2.941609'),
('NAQ0033158', '44.81125', '-0.473882', '45.068848', '-0.373017'),
('NOR0076066', '49.611486', '1.245959', '49.458957', '1.121751'),
('NOR0076073', '49.544169', '0.949823', '49.527064', '1.185118'),
('PDL0049111', '47.438056', '-0.217549', '47.394366', '-0.427651'),
('SUD0006006', '-22.298351', '166.440483', '43.727600', '7.415600'),
('SUD0006036', '43.628936', '6.877669', '43.605126', '7.075492'),
('SUD0006041', '-22.298351', '166.440483', '43.738400', '7.424600'),
('SUD0006054', '-22.298351', '166.440483', '43.738400', '7.424600')
) AS v(code, old_latitude, old_longitude, latitude, longitude)
WHERE c.code = v.code
  AND c.latitude IS NOT DISTINCT FROM v.old_latitude::decimal(10,8)
  AND c.longitude IS NOT DISTINCT FROM v.old_longitude::decimal(11,8);
